question:
以下 CUDA kernel 启动后，每个线程块内的线程总数是多少？
```cuda
dim3 block(16, 4);
kernel<<<8, block>>>();
```

以下 CUDA 代码中，第 0 号块内第 0 号线程的全局线性线程 ID 是多少？
```cuda
__global__ void k() {
    int t = blockIdx.x * blockDim.x + threadIdx.x;
}
k<<<1, 64>>>();
```

以下 kernel 启动的线程总数是多少？
```cuda
dim3 grid(3, 2);
dim3 block(4, 4);
kernel<<<grid, block>>>();
```

以下 CUDA 代码中，gird 维度写错的编译错误类型是？
```cuda
dim3 grid(2, 2);
kernel<<<grid, grid>>>();
```（kernel 的形参为 block 维度）

以下代码中，变量 s 位于什么内存空间？
```cuda
__global__ void k() {
    __shared__ float s[64];
    s[threadIdx.x] = 1.0f;
}
```

以下代码存在什么问题？
```cuda
__global__ void k() {
    __shared__ int s;
    if (threadIdx.x == 0) s = 42;
    int v = s;  // 所有线程读
}
```

以下 kernel 中，动态共享内存大小由谁指定？
```cuda
__global__ void k() {
    extern __shared__ float sm[];
}
k<<<1, 32, 128>>>();
```

以下代码中，变量 v 存放在哪个空间？
```cuda
__global__ void k() {
    float v = 3.14f;
    v += 1.0f;
}
```

以下代码有什么内存问题？
```cuda
__global__ void k(float* d) {
    float* p = new float[16];  // 设备端
    p[0] = 1.0f;
}
```

以下 CUDA 代码中，d_a 初始化后 h_a 的内容是什么？
```cuda
float h_a[4] = {1, 2, 3, 4};
float* d_a; cudaMalloc(&d_a, 16);
cudaMemcpy(d_a, h_a, 16, cudaMemcpyHostToDevice);
cudaMemset(d_a, 0, 16);
cudaMemcpy(h_a, d_a, 16, cudaMemcpyDeviceToHost);
```

以下 kernel 中，所有块都执行到 __syncthreads() 后，全局内存可见性如何？
```cuda
__global__ void k(float* g) {
    __shared__ float s[1];
    s[0] = g[0];
    __syncthreads();
    g[0] = s[0] + 1;
}
```

以下代码中，atomicAdd 的返回值是什么？
```cuda
__global__ void k(int* counter) {
    int old = atomicAdd(counter, 1);
}
```

以下代码执行后，g 的值是多少（假设 g 初始为 0，单块 32 线程各 atomicAdd(g, 1)）？
```cuda
__global__ void k(int* g) {
    atomicAdd(g, 1);
}
k<<<1, 32>>>();
```

以下代码存在什么问题？
```cuda
__global__ void k(int* g) {
    if (threadIdx.x < 16) { g[0] = 1; }
    __syncthreads();
    if (threadIdx.x >= 16) { g[1] = g[0]; }
}
```

以下代码中，第二个 kernel 何时执行？
```cuda
kernel<<<1, 32>>>();
cudaStreamSynchronize(stream);
kernel2<<<1, 32>>>();
```

以下 CUDA 代码中，g[0] 的最终值是多少？
```cuda
__global__ void k(int* g) {
    __shared__ int s;
    if (threadIdx.x == 0) { s = 5; }
    __syncthreads();
    if (threadIdx.x == 1) { s += 2; }
    __syncthreads();
    if (threadIdx.x == 0) { g[0] = s; }
}
k<<<1, 32>>>();
```

以下共享内存访问是否产生 bank conflict？
```cuda
__shared__ float s[32];
float v = s[threadIdx.x * 2];
```

以下共享内存访问是否产生 bank conflict？
```cuda
__shared__ float s[32];
float v = s[threadIdx.x];
```

以下规约（reduce）代码中，最后结果 g[0] 是多少（d 为 0..31 的平方和）？
```cuda
__global__ void k(int* g, int* d) {
    __shared__ int s[32];
    s[threadIdx.x] = d[threadIdx.x] * d[threadIdx.x];
    __syncthreads();
    if (threadIdx.x == 0) {
        int sum = 0;
        for (int i = 0; i < 32; i++) sum += s[i];
        g[0] = sum;
    }
}
```
